def maximum_four_pick_score(a,b):
    negative=-10**30;dp=[0]+[negative]*4
    for value in b:
        for chosen in range(3,-1,-1):dp[chosen+1]=max(dp[chosen+1],dp[chosen]+a[chosen]*value)
    return dp[4]

